mapper.select:
select a.content ->> '$.businessName' AS business_name, a.content ->> '$.area' AS area, a.content ->> '$.companyName' AS company_name, a.content ->> '$.detailedAddress' AS detailed_address, a.content ->> '$.customerName' AS customer_name, a.content ->> '$.mobile' AS mobile, a.content ->> '$.code' AS code, a.content ->> '$.voltageLevel' AS voltage_level, a.content ->> '$.electricityCapacity' AS electricity_capacity, a.form_id, a.status, a.sub_status, DATE_FORMAT(a.time_submit, '%Y-%m-%d %T') AS time_submit, DATE_FORMAT(a.time_reception, '%Y-%m-%d %T') AS time_reception, DATE_FORMAT(a.time_finished, '%Y-%m-%d %T') AS time_finished, a.flag, a.remark, e.realname, d.name AS org_name, (CASE (b.user_id = #{listParam.userId} AND a.status != '待处理' AND a.status != '已终止') OR a.status = '处理中' OR a.status = '已处理' WHEN TRUE THEN '已处理' ELSE ( CASE a.status = '已终止' WHEN TRUE THEN '已终止' ELSE '待处理' END ) END) AS user_status from wf_form a LEFT JOIN wf_form_flow b ON b.form_id = a.form_id AND b.create_user_id = #{listParam.userId} LEFT JOIN r_user_tenant c ON c.user_id = b.user_id LEFT JOIN b_organization d ON d.organization_id = a.current_org_id LEFT JOIN b_user e ON e.user_id = b.user_id
a.flag != -1 and a.create_user_id = #{listParam.userId}
and a.sub_status = #{listParam.searchMap.status}
and (a.content->> '$.code' like CONCAT('%',#{listParam.searchMap.name},'%') OR a.content->> '$.businessName' like CONCAT('%',#{listParam.searchMap.name},'%') )
and a.content->>'$.businessName' like CONCAT('%',#{listParam.searchMap.businessName},'%')
group by a.content,a.form_id,a.status,a.sub_status,a.time_submit,a.time_reception,a.time_finished,a.flag,a.remark, e.realname, d.name, user_status order by a.time_submit DESC

select a.content ->> "$.businessName" AS business_name, a.content ->> "$.area" AS area, a.content ->> "$.companyName" AS company_name, a.content ->> "$.detailedAddress" AS detailed_address, a.content ->> "$.customerName" AS customer_name, a.content ->> "$.mobile" AS mobile, a.content ->> "$.code" AS code, a.content ->> "$.voltageLevel" AS voltage_level, a.content ->> "$.electricityCapacity" AS electricity_capacity, a.form_id, a.status, a.sub_status, a.current_org_id AS organization_id, DATE_FORMAT(a.time_submit, '%Y-%m-%d %T') AS time_submit, DATE_FORMAT(a.time_reception, '%Y-%m-%d %T') AS time_reception, DATE_FORMAT(a.time_finished, '%Y-%m-%d %T') AS time_finished, a.flag, a.remark, e.`realname`, d.`name` AS org_name,
(CASE a.`status` = '处理中' OR a.`status` = '已处理' WHEN TRUE THEN '已处理' ELSE ( CASE a.`status` = '已终止' WHEN TRUE THEN '已终止' ELSE '待处理' END ) END) AS user_status
(CASE (a.`status` = '处理中' AND a.`sub_status` = '待处理') WHEN TRUE THEN '待处理' ELSE ( CASE a.`status` = '已终止' WHEN TRUE THEN '已终止' ELSE '已处理' END ) END) AS user_status
(CASE a.`sub_status` = '待处理' WHEN TRUE THEN '待处理' ELSE ( CASE a.`status` = '已终止' WHEN TRUE THEN '已终止' ELSE '已处理' END ) END) AS user_status
(CASE a.`sub_status` = '待处理' WHEN TRUE THEN '待处理' ELSE ( CASE a.`status` = '已终止' WHEN TRUE THEN '已终止' ELSE '已处理' END ) END) AS user_status
from wf_form a LEFT JOIN wf_form_flow b ON b.form_id = a.form_id AND b.create_user_id = #{userInfo.userId} LEFT JOIN wf_form_flow g ON g.form_id = a.form_id AND g.action_type = '已回复' LEFT JOIN r_user_tenant c ON c.user_id = b.user_id LEFT JOIN b_organization d ON d.organization_id = a.current_org_id LEFT JOIN b_user e ON e.user_id = g.user_id LEFT JOIN r_user_role f ON f.user_id = b.create_user_id
a.flag != -1
and a.sub_status = #{listParam.searchMap.status}
and (a.content->> "$.code" like CONCAT('%',#{listParam.searchMap.name},'%') OR a.content->> "$.businessName" like CONCAT('%',#{listParam.searchMap.name},'%') )
and a.modify_time >= #{listParam.searchMap.starttime} AND a.modify_time <= #{listParam.searchMap.endtime}
and a.content->>"$.businessName" like CONCAT('%',#{listParam.searchMap.businessName},'%')
and b.create_user_id = #{userInfo.userId}
and a.current_org_id in
#{org.id}
a.create_user_id = #{userInfo.userId}
group by a.content,a.form_id,a.STATUS,a.sub_status,a.time_submit,a.time_reception,a.time_finished,a.flag,a.remark, e.`realname`, d.`name`, `user_status`
having user_status = #{listParam.searchMap.status}
order by a.time_submit DESC

select count(1) AS new_consulting_count
from wf_form a
where a.flag != -1 AND a.create_time between #{startTime} and #{endTime}

mapper.sql:
select row_number() over (order by a.modify_time desc) as row_num , json_unquote(json_extract(a.content, '$.businessName')) AS business_name , json_unquote(json_extract(a.content, '$.area')) AS area , json_unquote(json_extract(a.content, '$.companyName')) AS company_Name , json_unquote(json_extract(a.content, '$.detailedAddress')) AS detailed_address , json_unquote(json_extract(a.content, '$.customerName')) AS customer_name , json_unquote(json_extract(a.content, '$.mobile')) AS mobile , json_unquote(json_extract(a.content, '$.code')) AS code , json_unquote(json_extract(a.content, '$.voltageLevel')) AS voltage_level , json_unquote(json_extract(a.content, '$.electricityCapacity')) AS electricity_capacity , a.form_id , a.status , a.sub_status , a.current_org_id AS organization_id , DATE_FORMAT(a.time_submit, '%Y-%m-%d %T') AS time_submit , DATE_FORMAT(a.time_reception, '%Y-%m-%d %T') AS time_reception , DATE_FORMAT(a.time_finished, '%Y-%m-%d %T') AS time_finished , DATE_FORMAT(a.modify_time, '%Y-%m-%d %T') AS modify_time , a.flag , a.remark , d.`name` AS org_name , p.organization_id as preselected_org_id , p.`name` as preselected_org_name,
(case when a.`status` = '处理中' or a.`status` = '已处理' then '已处理' when a.status = '已完结' then '已完结' when a.status = '已终止' then '已终止' else (case when a.`status` = '已终止' then '已终止' else '待处理' end) end) as user_status
(case when (a.`status` = '处理中' and a.`sub_status` = '待处理') then '待处理' when a.status = '已完结' then '已完结' when a.status = '已终止' then '已终止' else (case when a.`status` = '已终止' then '已终止' else '已处理' end) end) AS user_status
(case when a.`sub_status` = '待处理' then '处理中' when a.status = '已完结' then '已完结' when a.status = '已终止' then '已终止' else (case when a.`status` = '已终止' then '已终止' else '已处理' end) end) AS user_status
(case when a.`sub_status` = '待处理' then '待处理' when a.status = '已完结' then '已完结' when a.status = '已终止' then '已终止' else (case when a.`status` = '已终止' then '已终止' else '已处理' end) end) AS user_status
from wf_form a join b_organization d on d.organization_id = a.current_org_id left join b_organization p on p.organization_id = a.preselected_org_id left join wf_form_flow b on b.form_id = a.form_id and b.create_user_id = #{userInfo.userId} /*LEFT JOIN r_user_tenant c ON c.user_id = b.user_id LEFT JOIN r_user_role f ON f.user_id = b.create_user_id*/ where a.flag = 1
and a.tenant_id = #{listParam.tenantId}
/*数据范围：所有*/
/*数据范围：当前租户*/ and a.tenant_id = #{userInfo.tenantId}
/*数据范围：集团*/ and a.tenant_id = #{userInfo.tenantId}
/*数据范围：公司*/ and a.current_org_id in
#{org.id}
/*数据范围：个人*/ and a.create_user_id = #{userInfo.userId}
and (json_unquote(json_extract(a.content, '$.code')) like CONCAT('%', #{listParam.searchMap.name}, '%') or json_unquote(json_extract(a.content, '$.businessName')) like CONCAT('%', #{listParam.searchMap.name}, '%'))
and json_unquote(json_extract(a.content, '$.businessName')) like CONCAT('%', #{listParam.searchMap.businessName}, '%')
and b.create_user_id = #{userInfo.userId}
and a.modify_time >= #{listParam.searchMap.starttime} and a.modify_time <= #{listParam.searchMap.endtime}
group by a.content,a.form_id,a.STATUS,a.sub_status,a.time_submit,a.time_reception,a.time_finished,a.modify_time,a.flag,a.remark, d.`name`, p.`name`, `user_status`
having user_status = #{listParam.searchMap.status}

mapper.select:
select wf.form_flow_id, wf.form_id, DATE_FORMAT(wf.time_action, '%Y-%m-%d %T') AS time_action, wf.user_id, wf.action_type, wf.action_content, wf.status, wf.sub_status from wf_form_flow wf
where wf.flag = 1 and wf.form_id = #{formId}
and wf.tenant_id = #{userInfo.tenantId}
order by wf.time_action asc

select
    wf.form_id,
    json_unquote(json_extract(wf.content, '$.businessName')) AS business_name,  json_unquote(json_extract(wf.content, '$.code')) AS code,
    DATE_FORMAT(wf.time_submit, '%Y-%m-%d %T') AS time_submit,
    DATE_FORMAT(wff.modify_time, '%Y-%m-%d %T') AS modify_time,
    bo.name as org_name,
    wff.action_content,
    wff.`status`
from wf_form_flow wff
left join wf_form wf on wf.form_id = wff.form_id
left join b_organization bo on bo.organization_id = wff.service_unit_id
where wf.flag = 1
and wff.`status` in ('已撤回', '已退回')


        /*数据范围：所有*/


        /*数据范围：当前租户*/
        and wf.tenant_id = #{userInfo.tenantId}


        /*数据范围：集团*/
        and wf.tenant_id = #{userInfo.tenantId}


        /*数据范围：公司*/
        and wff.service_unit_id in

            #{org.id}



        /*数据范围：个人*/
        and wf.create_user_id = #{userInfo.userId}


order by wff.modify_time desc

select row_number() over (order by a.modify_time desc) as row_num , json_unquote(json_extract(a.content, '$.businessName')) AS business_name , json_unquote(json_extract(a.content, '$.area')) AS area , json_unquote(json_extract(a.content, '$.companyName')) AS company_Name , json_unquote(json_extract(a.content, '$.detailedAddress')) AS detailed_address , json_unquote(json_extract(a.content, '$.customerName')) AS customer_name , json_unquote(json_extract(a.content, '$.mobile')) AS mobile , json_unquote(json_extract(a.content, '$.code')) AS code , json_unquote(json_extract(a.content, '$.voltageLevel')) AS voltage_level , json_unquote(json_extract(a.content, '$.electricityCapacity')) AS electricity_capacity , a.form_id , a.status , a.sub_status , a.current_org_id AS organization_id , DATE_FORMAT(a.time_submit, '%Y-%m-%d %T') AS time_submit , DATE_FORMAT(a.time_reception, '%Y-%m-%d %T') AS time_reception , DATE_FORMAT(a.time_finished, '%Y-%m-%d %T') AS time_finished , DATE_FORMAT(a.modify_time, '%Y-%m-%d %T') AS modify_time , a.flag , a.remark , d.`name` AS org_name , p.organization_id as preselected_org_id , p.`name` as preselected_org_name,
(case when a.`status` = '处理中' or a.`status` = '已处理' then '已处理' when a.status = '已完结' then '已完结' when a.status = '已终止' then '已终止' else (case when a.`status` = '已终止' then '已终止' else '待处理' end) end) as user_status
(case when (a.`status` = '处理中' and a.`sub_status` = '待处理') then '待处理' when a.status = '已完结' then '已完结' when a.status = '已终止' then '已终止' else (case when a.`status` = '已终止' then '已终止' else '已处理' end) end) AS user_status
(case when a.`sub_status` = '待处理' then '处理中' when a.status = '已完结' then '已完结' when a.status = '已终止' then '已终止' else (case when a.`status` = '已终止' then '已终止' else '已处理' end) end) AS user_status
(case when a.`sub_status` = '待处理' then '待处理' when a.status = '已完结' then '已完结' when a.status = '已终止' then '已终止' else (case when a.`status` = '已终止' then '已终止' else '已处理' end) end) AS user_status
from wf_form a join b_organization d on d.organization_id = a.current_org_id left join b_organization p on p.organization_id = a.preselected_org_id where a.flag = 1 and a.form_id = #{formId}
/*数据范围：所有*/
/*数据范围：当前租户*/ and a.tenant_id = #{userInfo.tenantId}
/*数据范围：集团*/ and a.tenant_id = #{userInfo.tenantId}
/*数据范围：公司*/ and a.current_org_id in
#{org.id}
/*数据范围：个人*/ and a.create_user_id = #{userInfo.userId}
group by a.content,a.form_id,a.STATUS,a.sub_status,a.time_submit,a.time_reception,a.time_finished,a.modify_time,a.flag,a.remark, d.`name`,p.`name`, `user_status`
